public class Issue93_insert_into_sorted_scores { public static void main(String[] args) { int[] v=new int[]{-12, 7, 10, 10}; int value=22; int[] r=new int[v.length+1]; for(int i=0;i<v.length;i++) r[i]=v[i]; r[v.length]=value; for(int i=0;i<r.length;i++) for(int j=0;j<r.length-i-1;j++) if(r[j]<r[j+1]) { int t=r[j]; r[j]=r[j+1]; r[j+1]=t; } for(int i=0;i<r.length-1;i++) System.out.print(r[i]+" "); } }
